&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;List Bullet&quot;&gt;Typically 8 or more years of relevant experience across clinical pricing, sponsor-side clinical finance, clinical trial budgeting, site payments, study operations, technology implementation, or product management; substantial sponsor-side industry experience may outweigh formal product-management tenure&lt;/span&gt;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233279&amp;quot;:false,&amp;quot;335559738&amp;quot;:120,&amp;quot;335559739&amp;quot;:120}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
